-- ============================================================================
-- Seed des points de programme de SECONDE (programme de 2de générale et
-- technologique) + RÉFÉRENCES d'automatismes + restructuration de la branche
-- Logique (décision C2).
-- ============================================================================
-- Source de vérité : docs/wip/arbre-notions/seed-2de.md (VALIDÉ INTÉGRALEMENT par
-- David le 2026-10-08 : puces multi-parties, discutables 1-5, L1-L4) ; fichier
-- GÉNÉRÉ — ne pas éditer à la main.
--   * Arbre : la notion « Connecteurs et contre-exemples » devient « Proposition
--     mathématique » (et, ou, non + statut des lettres et des égalités, venue de
--     « Quantificateurs et négation ») ; « contre-exemple » rejoint
--     « Raisonnements ». Nœuds RENOMMÉS / DÉPLACÉS (UPDATE), identifiants
--     préservés ; aucun point ni rangement ne visait la branche Logique.
--   * 200 points, codes 2-201…2-400 (l'ancien seed 2-001…2-185, grade NULL, reste
--     intact jusqu'à C5) ; 27 algorithme, 11 démonstration, 14 approfondissement.
--   * 58 références d'automatismes du grade '2' (dont 8 auto-références C13).
--
-- MIGRATION ADDITIVE (aucune ligne supprimée). Rollback (⚠️ scopé) :
--   delete from public.curriculum_point_automatismes where grade = '2';
--   delete from public.curriculum_points where grade = '2';
--   puis, pour l'arbre, les UPDATE inverses (Logique) :
--     « Proposition mathématique » → « Connecteurs et contre-exemples » ;
--     « statut des lettres et des égalités » → sous « Quantificateurs et
--     négation » (position 1, « négation d'une proposition » en 2) ;
--     « contre-exemple » → sous la notion renommée (position 1, « et, ou, non » en 0).
-- ⚠️ Ce rollback n'est anodin que tant qu'AUCUN usage ne s'accroche à ces
-- points. Supprimer un point efface EN SILENCE (ON DELETE CASCADE) : le suivi
-- élève (tables de curriculum_tracking), les rattachements d'exercices du prof
-- (exercise_curriculum_points), journal_entry_points, srs_anti_fraud_flags, et
-- les références d'automatismes d'AUTRES grades (1re, Tle…) qui viseraient ces
-- points ; question_template_points (ON DELETE RESTRICT) fait échouer le
-- rollback. Dès qu'un usage existe : DESTRUCTIF (données d'élèves mineurs) —
-- arrêt obligatoire et accord explicite de David (règle CLAUDE.md).
-- ============================================================================

-- ---- 1. L'arbre : branche Logique restructurée (C2) -------------------------

do $c2$
declare
	v_logique uuid;
	v_prop uuid;
	v_quant uuid;
	v_rais uuid;
	n integer;
begin
	select id into strict v_logique from public.classification_nodes
	 where kind = 'branch' and name = 'Logique';
	select id into strict v_prop from public.classification_nodes
	 where kind = 'notion' and name = 'Connecteurs et contre-exemples' and parent_id = v_logique;
	select id into strict v_quant from public.classification_nodes
	 where kind = 'notion' and name = 'Quantificateurs et négation' and parent_id = v_logique;
	select id into strict v_rais from public.classification_nodes
	 where kind = 'notion' and name = 'Raisonnements' and parent_id = v_logique;

	update public.classification_nodes set name = 'Proposition mathématique' where id = v_prop;
	get diagnostics n = row_count;
	if n <> 1 then raise exception 'C2 : renommage — % ligne(s)', n; end if;

	update public.classification_nodes set parent_id = v_prop, position = 0
	 where kind = 'subnotion' and name = 'statut des lettres et des égalités' and parent_id = v_quant;
	get diagnostics n = row_count;
	if n <> 1 then raise exception 'C2 : statut des lettres — % ligne(s)', n; end if;

	update public.classification_nodes set position = 1
	 where kind = 'subnotion' and name = 'et, ou, non' and parent_id = v_prop;
	get diagnostics n = row_count;
	if n <> 1 then raise exception 'C2 : et, ou, non — % ligne(s)', n; end if;

	update public.classification_nodes set parent_id = v_rais,
	       position = (select coalesce(max(c.position), -1) + 1 from public.classification_nodes c where c.parent_id = v_rais)
	 where kind = 'subnotion' and name = 'contre-exemple' and parent_id = v_prop;
	get diagnostics n = row_count;
	if n <> 1 then raise exception 'C2 : contre-exemple — % ligne(s)', n; end if;

	update public.classification_nodes set position = 1
	 where kind = 'subnotion' and name = 'négation d''une proposition' and parent_id = v_quant;
	get diagnostics n = row_count;
	if n <> 1 then raise exception 'C2 : négation — % ligne(s)', n; end if;
end $c2$;

