-- ---- 4. Vérifications (la migration échoue si le compte n'y est pas) --------

do $check$
declare
	v_pts integer; v_sans_noeud integer; v_refs integer; v_auto integer;
	v_algo integer; v_demo integer; v_appro integer; v_fluence integer;
	v_anciens integer; v_logique integer; v_noeuds integer;
begin
	select count(*) into v_pts from public.curriculum_points where grade = '2';
	select count(*) into v_sans_noeud from public.curriculum_points where grade = '2' and node_id is null;
	select count(*) into v_refs from public.curriculum_point_automatismes where grade = '2';
	select count(*) into v_auto from public.curriculum_point_automatismes a
	  join public.curriculum_points p on p.id = a.point_id
	 where a.grade = '2' and p.grade = '2';
	select count(*) into v_algo from public.curriculum_points where grade = '2' and kind = 'algorithme';
	select count(*) into v_demo from public.curriculum_points where grade = '2' and kind = 'demonstration';
	select count(*) into v_appro from public.curriculum_points where grade = '2' and exigence = 'approfondissement';
	select count(*) into v_fluence from public.curriculum_points where grade = '2' and regime_acquisition <> 'diversite';
	-- L'ancien seed (grade NULL, rattaché aux objectifs) est intact.
	select count(*) into v_anciens from public.curriculum_points
	 where code ~ '^2-(0\d\d|1[0-7]\d|18[0-5])$' and grade is null and objective_id is not null;
	-- Branche Logique : 4 notions, sous-notions à leur nouvelle place.
	select count(*) into v_logique
	  from public.classification_nodes s
	  join public.classification_nodes n on n.id = s.parent_id
	  join public.classification_nodes b on b.id = n.parent_id and b.kind = 'branch' and b.name = 'Logique'
	 where s.kind = 'subnotion'
	   and ((n.name = 'Proposition mathématique' and s.name in ('statut des lettres et des égalités', 'et, ou, non'))
	     or (n.name = 'Quantificateurs et négation' and s.name in ('pour tout, il existe', 'négation d''une proposition'))
	     or (n.name = 'Raisonnements' and s.name = 'contre-exemple'));
	select count(*) into v_noeuds from public.classification_nodes n
	  join public.classification_nodes b on b.id = n.parent_id and b.kind = 'branch' and b.name = 'Logique'
	 where n.kind = 'notion';
	if v_pts <> 200 or v_sans_noeud <> 0 or v_refs <> 58 or v_auto <> 8
	   or v_algo <> 27 or v_demo <> 11 or v_appro <> 14 or v_fluence <> 0
	   or v_anciens <> 185 or v_logique <> 5 or v_noeuds <> 4 then
		raise exception 'seed 2de incohérent : points=%, sans nœud=%, réfs=%, auto=%, algo=%, dém=%, appro=%, non-diversité=%, anciens=%, logique=%, notions logique=%',
			v_pts, v_sans_noeud, v_refs, v_auto, v_algo, v_demo, v_appro, v_fluence, v_anciens, v_logique, v_noeuds;
	end if;
end $check$;
